WITH recent_products AS (SELECT * FROM products WHERE price > 590 AND launch_date < '2024-08-01' AND category = 'Books'), summary AS (SELECT CASE WHEN cost >= 690 THEN 'high' WHEN cost >= 310 THEN 'mid' ELSE 'low' END AS cost_bucket, COUNT(*) AS num_products FROM recent_products GROUP BY CASE WHEN cost >= 690 THEN 'high' WHEN cost >= 310 THEN 'mid' ELSE 'low' END) SELECT cost_bucket, num_products FROM summary ORDER BY cost_bucket DESC
